\end{equation}
is surjective.

\label{cor:torsionfree}
    Let $X$ be a smooth variety defined over an algebraically closed field $k$. Fix $\ell$ a prime number distinct from the characteristic of $k$.  All the torsion classes in the \'etale cohomology $H^{i+1}(X, \mathbb{Z}_\ell(i)) (i \geq 0)$ are supported in divisors, and $H^{i+1}(X, \mathbb{Z}_\ell(i))/N^1H^{i+1}(X, \mathbb{Z}_\ell(i))$ is torsion free.

    The same conclusion holds if $X$ is a complex variety and we use singular cohomology with $\mathbb{Z}$-coefficients.

\begin{align}\label{eq:higherclassmapet2}
    cl^{q, p}: &\text{CH}^q(X, p, \mathbb{Z}/m) \xrightarrow{\cong} H_{\text{Zar}}^{2q-p}(X, \tau^{\leq q}R\pi_*(\mu_m^{\otimes q}))\\ 
    \to &H_{\text{Zar}}^{2q-p}(X, R\pi_*(\mu_m^{\otimes q}))\xrightarrow{\cong} H^{2q-p}_\text{\'et}(X, \mu_m^{\otimes q}), p, q\geq 0.\nonumber
\end{align}

If $X$ is smooth of equi-dimension $d$, the higher cycle class map is a composition of isomorphisms
\begin{align*}
    &\text{CH}_0(X, n, \mathbb{Z}/m) \xrightarrow{\cong} H_{\text{Zar}}^{2d-n}(X, \tau^{\leq d}R\pi_*(\mu_m^{\otimes d})) \\
    \xrightarrow{\cong} &H_{\text{Zar}}^{2d-n}(X, R\pi_*(\mu_m^{\otimes d}))\xrightarrow{\cong} H^{2d-n}_\text{\'et}(X, \mu_m^{\otimes d}) \cong H_n^{\text{BM}}(X, \mathbb{Z}/m),
\end{align*}
where for the second isomorphism, we use the fact that $R\pi_*(\mu_m^{\otimes d})$ has no cohomology in degree $d+1$ and higher.

In general, we use induction on dimension. Dimension $0$ case is trivially true. Write $X$ as the disjoint union of its singular locus $Z$ and smooth locus $U$. Then the statement is true for both $Z$ (by induction hypothesis) and $U$ (because it is smooth). Since the cycle class maps are compatible with the localization sequence for higher Chow groups and Borel-Moore homology (Proposition \ref{prop:func}), we have a commutative diagram of localization long exact sequences for higher Chow groups and Borel-Moore homology with $\mathbb{Z}/m$-coefficients:
\[
\begin{CD}
   \ldots \text{CH}_0(Z, j) @>>>\text{CH}_0(X, j) @>>>\text{CH}_0(U, j) @>>>\text{CH}_0(Z, j-1) \ldots \\
    @VVcl_{0, j}^Z V @VVcl_{0, j}^X V @VVcl_{0, j}^U V @VVcl_{0, j-1}^ZV\\
   \ldots H_{j}^{\text{BM}}(Z) @>>>H_{j}^{\text{BM}}(X) @>>>H_{j}^{\text{BM}}(U) @>>>H_{j-1}^{\text{BM}}(Z)\ldots .\\
\end{CD}
\]
So the desired isomorphism follows from five lemma.

\begin{align*}
        &\text{CH}_0(X, n, \mathbb{Z}/m) \xrightarrow{\cong} H_{\text{Zar}}^{2d-n}(X, \tau^{\leq d}R\pi_*(\mu_m^{\otimes d})) \\
        \xrightarrow{\cong} &H_{\text{Zar}}^{2d-n}(X, R\pi_*(\mu_m^{\otimes d}))\xrightarrow{\cong} H^{2d-n}_\text{\'et}(X, \mu_m^{\otimes d}) \cong H_n^{\text{BM}}(X, \mathbb{Z}/m),
    \end{align*}

\[
    \begin{CD}
       \ldots \text{CH}_0(Z, j) @>>>\text{CH}_0(X, j) @>>>\text{CH}_0(U, j) @>>>\text{CH}_0(Z, j-1) \ldots \\
        @VVcl_{0, j}^Z V @VVcl_{0, j}^X V @VVcl_{0, j}^U V @VVcl_{0, j-1}^ZV\\
       \ldots H_{j}^{\text{BM}}(Z) @>>>H_{j}^{\text{BM}}(X) @>>>H_{j}^{\text{BM}}(U) @>>>H_{j-1}^{\text{BM}}(Z)\ldots .\\
    \end{CD}
    \]

\label{prop:bockstein}
    Let $X$ be a variety defined over an algebraically closed field and $\ell$ a prime number different from the field characteristic. We have a commutative diagram of long exact sequences:
    \[
    \begin{CD}
        \ldots \to \text{CH}_i(X, j, \mathbb{Z}_\ell) @>\times \ell^n>> \text{CH}_i(X, j, \mathbb{Z}_\ell) @>>> \text{CH}_i(X, j, \mathbb{Z}/\ell^n) \\
         @VVV @VVV @VVV  \\
        \ldots \to H_{2i+j}^{\text{BM}}(X, \mathbb{Z}_\ell(i)) @>\times \ell^n >> H_{2i+j}^{\text{BM}}(X, \mathbb{Z}_\ell(i)) @>>> H_{2i+j}^{\text{BM}}(X, \mathbb{Z}/\ell^n(i)) 
    \end{CD}
    \]
    \[
    \begin{CD}
        \to {\text{CH}}_i(X, j-1, \mathbb{Z}_\ell) @>\times \ell^n >> \text{CH}_i(X, j-1, \mathbb{Z}_\ell) @>>> \text{CH}_i(X, j-1, \mathbb{Z}/\ell^n)\ldots \\
         @VVV @VVV @VVV  \\
        \to H_{2i+j-1}^{\text{BM}}(X, \mathbb{Z}_\ell(i)) @>\times \ell^n >> H_{2i+j-1}^{\text{BM}}(X, \mathbb{Z}_\ell(i)) @>>> H_{2i+j-1}^{\text{BM}}(X, \mathbb{Z}/\ell^n(i))\ldots
    \end{CD}
    \]

\[
    \begin{CD}
        \ldots \to \text{CH}_i(X, j, \mathbb{Z}_\ell) @>\times \ell^n>> \text{CH}_i(X, j, \mathbb{Z}_\ell) @>>> \text{CH}_i(X, j, \mathbb{Z}/\ell^n) \\
         @VVV @VVV @VVV  \\
        \ldots \to H_{2i+j}^{\text{BM}}(X, \mathbb{Z}_\ell(i)) @>\times \ell^n >> H_{2i+j}^{\text{BM}}(X, \mathbb{Z}_\ell(i)) @>>> H_{2i+j}^{\text{BM}}(X, \mathbb{Z}/\ell^n(i)) 
    \end{CD}
    \]

\[
    \begin{CD}
        \to {\text{CH}}_i(X, j-1, \mathbb{Z}_\ell) @>\times \ell^n >> \text{CH}_i(X, j-1, \mathbb{Z}_\ell) @>>> \text{CH}_i(X, j-1, \mathbb{Z}/\ell^n)\ldots \\
         @VVV @VVV @VVV  \\
        \to H_{2i+j-1}^{\text{BM}}(X, \mathbb{Z}_\ell(i)) @>\times \ell^n >> H_{2i+j-1}^{\text{BM}}(X, \mathbb{Z}_\ell(i)) @>>> H_{2i+j-1}^{\text{BM}}(X, \mathbb{Z}/\ell^n(i))\ldots
    \end{CD}
    \]

We have a commutative diagram of short exact sequences of coefficients ($n, m \geq 0$):
\[
\begin{CD}
    0 @>>> \mathbb{Z}_\ell @>\times \ell^n>> \mathbb{Z}_\ell @>\mod \ell^n>> \mathbb{Z}/\ell^n @>>> 0\\
    @| @VV\mod \ell^m V @VV\mod \ell^{n+m}V @| @|\\
    0 @>>> \mathbb{Z}/\ell^m @>>> \mathbb{Z}/\ell^{n+m} @>>> \mathbb{Z}/\ell^n @>>> 0.\\
\end{CD}
\]
This induces a commutative diagram of long exact sequences (written vertically), 
\[
\begin{CD}
     \text{CH}_i(X, j, \mathbb{Z}_\ell) @>{\mod \ell^m}>> \text{CH}_i(X, j, \mathbb{Z}/\ell^m) @>cl_{i, j}>> H_{2i+j}^{\text{BM}}(X, \mathbb{Z}/{\ell^m}(i)) \\
    @VV\times \ell^n V @VVV @VVV \\
     \text{CH}_i(X, j, \mathbb{Z}_\ell) @>{\mod \ell^{n+m}}>> \text{CH}_i(X, j, \mathbb{Z}/{\ell^{n+m}}) @>cl_{i, j}>> H_{2i+j}^{\text{BM}}(X, \mathbb{Z}/{\ell^{n+m}}(i))\\
    @VV\mod \ell^n V @VV\mod \ell^n V @VV\mod \ell^n V \\
      \text{CH}_i(X, j, \mathbb{Z}/\ell^n) @=\text{CH}_i(X, j, \mathbb{Z}/\ell^n) @>cl_{i, j}>> H_{2i+j}^{\text{BM}}(X, \mathbb{Z}/{\ell^n}(i))\\
      @VVV @VVV @VVV\\
      \text{CH}_i(X, j-1, \mathbb{Z}_\ell)@>{\mod \ell^m}>> \text{CH}_i(X, j-1, \mathbb{Z}/\ell^m) @>cl_{i, j-1}>> H_{2i+j-1}^{\text{BM}}(X, \mathbb{Z}/{\ell^m}(i))\\
      @VV\times \ell^n V @VVV @VVV \\
     \text{CH}_i(X, j-1, \mathbb{Z}_\ell) @>{\mod \ell^{n+m}}>> \text{CH}_i(X, j-1, \mathbb{Z}/{\ell^{n+m}}) @>cl_{i, j-1}>> H_{2i+j-1}^{\text{BM}}(X, \mathbb{Z}/{\ell^{n+m}}(i)),
\end{CD}
\]
where the first two columns are long exact sequences of higher Chow groups constructed in Lemma \ref{lem:modN}, and the last column is the Bockstein long exact sequence of Borel-Moore homology induced by the exact sequence $0 \to \mathbb{Z}/\ell^m \to \mathbb{Z}/\ell^{n+m} \xrightarrow{\mod \ell^n} \mathbb{Z}/\ell^n \to 0$.

Then we have a commutative diagram after taking the inverse limit with respect to $m$.
\[
\begin{CD}
     \text{CH}_i(X, j, \mathbb{Z}_\ell) @>>> \lim \limits_{\xleftarrow[m]{}}\text{CH}_i(X, j, \mathbb{Z}/\ell^m) @>cl_{i, j}>> H_{2i+j}^{\text{BM}}(X, \mathbb{Z}_\ell(i)) \\
    @VV\times \ell^n V @VVV @VV\times \ell^nV \\
     \text{CH}_i(X, j, \mathbb{Z}_\ell) @>>> \lim \limits_{\xleftarrow[m]{}}\text{CH}_i(X, j, \mathbb{Z}/{\ell^{n+m}}) @>cl_{i, j}>> H_{2i+j}^{\text{BM}}(X, \mathbb{Z}_\ell(i))\\
    @VV\mod \ell^n V @VV\mod \ell^n V @VV\mod \ell^n V \\
      \text{CH}_i(X, j, \mathbb{Z}/\ell^n) @=\text{CH}_i(X, j, \mathbb{Z}/\ell^n) @>cl_{i, j}>> H_{2i+j}^{\text{BM}}(X, \mathbb{Z}/{\ell^n}(i))\\
      @VVV @VVV @VVV\\
      \text{CH}_i(X, j-1, \mathbb{Z}_\ell)@>>> \lim \limits_{\xleftarrow[m]{}}\text{CH}_i(X, j-1, \mathbb{Z}/\ell^m) @>cl_{i, j-1}>> H_{2i+j-1}^{\text{BM}}(X, \mathbb{Z}_\ell(i))\\
      @VV\times \ell^n V @VVV @VV\times \ell^nV \\
     \text{CH}_i(X, j-1, \mathbb{Z}_\ell) @>>> \lim \limits_{\xleftarrow[m]{}}\text{CH}_i(X, j-1, \mathbb{Z}/{\ell^{n+m}}) @>cl_{i, j-1}>> H_{2i+j-1}^{\text{BM}}(X, \mathbb{Z}_\ell(i)).
\end{CD}
\]
The right column is still a long exact sequence since every Borel-Moore homology group is finite and the Mittag-Leffler condition is satisfied.
This proves the desired statement.

