\label{lem:image_corr}
    Keep the same notations as in Definition \ref{defn:corr}. If $Y \xrightarrow{p\times q} Z\times X$ is generically finite of degree $d$ onto its image, then we have the following formula:
\begin{equation}\label{eq:push-pull}
    Y_*=d \cdot \Gamma_{Y*},
\end{equation}
where $\Gamma_Y \in \text{CH}_{\dim Y}(Z\times X)$ is the cycle class of the image of $Y$. 

Consequently, if $Y$ is birational to its image, or if we consider higher Chow groups or cohomology with coefficients in which $d$ is invertible, the image of $Y_*$ is the same as $\Gamma_{Y*}$.

\label{lem:contain}
    Keep the same notations as in Convention \ref{conv}.
    We have $$\tilde{N}_{c+1, \text{cyl}}H^k(X, A) \subset \tilde{N}_{c, \text{cyl}}H^k(X, A), c\geq 1.$$

\label{lem:birational}
    Let $X$ be a smooth projective variety of dimension $d$ defined over an algebraically closed field. Fix a prime number $\ell$ different from the field characteristic. All cohomology groups considered are \'etale cohomology groups. The following invariants are stable birational invariants of $X$.
    \begin{enumerate}
        \item The kernel and cokernel of the cycle class map 
        \[
        A_1(X)\otimes \mathbb{Z}_\ell \to H^{2d-2}(X, \mathbb{Z}_\ell(d-1)).
        \]

        \item The kernel and cokernel of the cycle class maps
        \begin{equation}\label{eq:highercyc}
            \lim \limits_{\xleftarrow[n]{}}\text{CH}_1({X}, r, \mathbb{Z}/\ell^n \mathbb{Z}) \to H^{2d-2-r}({X}, \mathbb{Z}_\ell(d-1)).
        \end{equation}

        \item The quotients $$H_{i}(X, \mathbb{Z}_\ell)/\tilde{N}_{1, \text{cyl}}H_{i}(X, \mathbb{Z}_\ell)=H^{2d-i}(X, \mathbb{Z}_\ell)/\tilde{N}_{1, \text{cyl}}H^{2d-i}(X, \mathbb{Z}_\ell),$$ $$H^{2d-3}(X, \mathbb{Z}_\ell)/\tilde{N}^{d-2}H^{2d-3}(X, \mathbb{Z}_\ell),$$
        and 
        $$H^{2d-3}(X, \mathbb{Z}_\ell)/{N}^{d-2}H^{2d-3}(X, \mathbb{Z}_\ell).$$


    \end{enumerate}

\label{def:RelCycle}
Let $X, S$ be finite type reduced separated $k$-schemes. An equi-dimensional family of relative cycles of dimension $r$ (or simply $r$-cycles) over $S$ is a formal linear combination of integral subschemes $\Gamma_S=\sum m_i Z_i, Z_i \subset S \times X, m_i \in \mathbb{Z}$, such that 
\begin{enumerate}
\item Each $Z_i$ dominates one irreducible component of $S$
\item Each non-empty fiber of $Z_i \to S$ has pure dimension $r$.
\item A fat point condition is satisfied (\cite[Definition 3.1.3]{SV_Chow_Sheaves}).
\item A field of definition condition is satisfied (\cite[Lemma 3.3.9 and the ensuing paragraph]{SV_Chow_Sheaves}). 
\end{enumerate} 
Each $Z_i$ is called a \emph{component} of $\Gamma_S$.
We write $\Gamma_{S}^+$ and $\Gamma_{S}^-$ as the \emph{positive and negative parts}, i.e. the sum of $Z_i$'s with positive and negative coefficients.

\label{thm:filtered}
Keep the same assumptions as in Theorem \ref{thm:filtered_sm}. 
Also assume that $X$ is separably rationally connected in codimension one.
Then there is
\begin{enumerate}
    \item an equi-dimensional family of one-cycles $V\leftarrow \Gamma_V \to X$ over a normal quasi-projective variety  $V$,  with a morphism $f: V \to U$, and a lifting $v_0, v_1 \in V$ of the points $u_0, u_1 \in U$;
    \item an equi-dimensional family of one-cycles $T \leftarrow \Gamma_T \to X$ over a two pointed connected projective curve $(T, t_0, t_1)$, where $t_0, t_1$ are smooth points of $T$;
    \item\label{cond:3sm} an open subset $U^0\subset U$ such that for any chosen point $u$ in $U^0$, for any pair of points $v, v'$ in the inverse image of $u$ in $V$, an equi-dimensional family of one-cycles $$(T_{v, v'}, t_{v, v'}^v, t_{v, v'}^{v'})\leftarrow \Gamma_{v, v'} \to X, $$ over a connected two pointed projective curve $(T_{v, v'}, t_{v, v'}^v, t_{v, v'}^{v'})$, where $t_{v, v'}^v$, $t_{v, v'}^{v'}$ are smooth points of $T_{v, v'}$;
    \item after choosing a point $u \in U^0$, an equi-dimensional family of one-cycles $W\leftarrow \Gamma_W \to X$ over a normal projective variety $W$ (depending on $u \in U^0$),
\end{enumerate} 
such that 
\begin{enumerate}
    \item[(i)] The morphism $f: V \to U$ is generically finite, surjective and projective.

    \item[(ii)]  $f^*\Gamma_U=\Gamma_V$ as equi-dimensional family of one-cycles over $V$.

    \item[(iii)] There is a morphism
    \[
    \Psi: V\coprod T\coprod (\coprod_{v, v' \in f^{-1}(u)}T_{v, v'})\to W,
    \]
    such that $\Gamma_V \coprod \Gamma_T \coprod (\coprod_{v, v'}\Gamma_{v, v'})=\Psi^*\Gamma_W$.

    \item[(iv)] The morphism $\Psi$ maps the pair of points $(v_0, t_0)$ (resp. $(v_1, t_1)$, $(v, t_{v, v'}^v)$, $(v', t_{v, v'}^{v'})$) to the same point in the smooth locus of $W$. It also maps $v_0$, $v_1$, and every singular point in $T, T_{v, v'}$ to the smooth locus of $W$. 

    \item[(v)]  The family of cycles $\Gamma_T\to T$ is constant. So necessarily, for each point $t$ of $T$,  $\Gamma_T|_{t}=\gamma$.


\item[(vi)] The family of cycles $\Gamma_{v, v'}\to T_{v, v'}$ is constant. So necessarily, for each point $t \in T_{v, v'}$, $\Gamma_{v, v'}|_t=\Gamma_U|_u$.
\end{enumerate}
In characteristic $0$, we may take $W$ to be smooth and projective.

\label{def:deformation}
    Let $X$ be a proper scheme over an algebraically closed field. A \emph{deformation equivalence} (of curves mapping to $X$) is a diagram $(B, b_1, b_2) \leftarrow S \to X$, where    
\begin{enumerate}
    \item $(B, b_1, b_2)$ is a two pointed connected curve with smooth marked points $b_i$, 
    \item $S\to B$ is flat, proper, with fibers of pure dimension $1$.
\end{enumerate}

The $b_i$ and the intersection points of different irreducible components of $B$ are the \emph{pivot points}.

\label{def:3nodal}
    A deformation equivalence as in Definition \ref{def:deformation} is called \emph{nodal} (or \emph{$2$-nodal}) if all fibers are nodal curves (singularities like $2$ coordinate axes $(xy=0)\subset\mathbb{A}^2$).
We call a deformation \emph{$3$-nodal} if all but finitely many fibers are nodal curves, and the pivot fibers have only nodes and $3$-nodal points as singularities.

\label{lem:r-connect}
    Let $X$ be a smooth projective variety defined over an algebraically closed  field $k$. Fix any positive integer $r$. There is a family of smooth curves in $X \times \mathbb{P}^1$:
    $\mathbf{L}_r \subset S \times X \times \mathbb{P}^1$ satisfying the following condition: 
    \begin{enumerate}
        \item For any length $r$ subscheme of $X \times \mathbb{P}^1$ whose embedding dimension is $1$, the subfamily of curves that pass through this subscheme is non-empty and irreducible;
        \item Let $M \leftarrow \mathcal{L}_r \xrightarrow{F} X \times \mathbb{P}^1, \sigma_i: M \to \mathcal{L}, i=1, \ldots, r,$ be the universal family parameterizing curves in $\mathbf{L}_r$ with $r$-distinct points. Then the evaluation map \[
        ev=\prod_{i=1}^r F\circ \sigma_i: M \to \prod_{i=1}^r(X \times \mathbb{P}^1) \]
        is flat.
    \end{enumerate}

\label{const:lifting}
     In the following, we often need to lift finitely many families of curves $S \leftarrow Z_i \to X$ to families of curves $S \to {Z}_i \to X \times \mathbb{P}^1$ such that the images of ${Z}_i$ are disjoint.
     One way to do this is to choose different points $p_{i}$ in $\mathbb{P}^1$ and use the compositions $Z_i \to X \cong X\times \{p_{i}\} \to X \times \mathbb{P}^1$).

\begin{align*}
        \textbf{CI}&=\{(u, W)|u \in U, \tilde{p}_i\circ \sigma_i(u)\in \cap_{D \in W}D, W\subset {H^0(X\times \mathbb{P}^1, \mathcal{O}_{X\times \mathbb{P}^1}(A))}, \dim W=d \}\\
        &\subset U \times \text{Grass}(d, H^0(X\times \mathbb{P}^1, \mathcal{O}_{X\times \mathbb{P}^1}(A))), d=\dim X.
    \end{align*}

\label{lem:deform}
    Let $X$ be a smooth projective variety defined over an algebraically closed field $k$. 
    Let $\mathbf{C}_r=\{\pi_i:C_i \to X, i=1, \ldots, r\} $ be a set of $r$ geometrically connected nodal curves in $X$. 
    Fix a family $\mathbf{L}_r\subset S \times X\times \mathbb{P}^1$ as in Definition  \ref{def:join}. 
    \begin{enumerate}
        \item $\text{Join}(\mathbf{C}_r, \mathbf{L}_r)$ is connected.
        \item $\text{Join}^\text{nodal}(\mathbf{C}_r, \mathbf{L}_r)$ is an open dense subset of $\text{Join}(\mathbf{C}_r, \mathbf{L}_r)$.

        \item For any two members of the family of curves $\text{Join}^{\text{nodal}}(\mathbf{C}_r, \mathbf{L}_r)$, there is a $3$-nodal deformation from one to the other over a connected curve, which is obtained by gluing the constant deformation family of the curves $C_1, \ldots C_r$ to a family of deformations of curves in $\mathbf{L}_r$.
        We can also modify the deformation at pivot points to make it nodal.
    \end{enumerate}

\label{prop:addtodeform}
    Keep the same notations as Theorem \ref{thm:filtered_sm}. Assume furthermore that $U$ is quasi-projective and that $\Gamma_U$, the family of cycles over $U$, is an effective nodal family of one-cycles.
    Then there is a generically finite dominant base change $f: V \to U$, a connected two pointed quasi-projective curve $(T, t_0, t_1)$, two families of $\mathbf{L}_s$-curves $\mathcal{L}_T \to T$ and $\mathcal{L}_V \to V$, a connected nodal curve $Z \to X$, two families of $r$-tuple of $L_2$-curves $r|\mathbf{L}_2|_V \to V$, $r|\mathbf{L}_2|_T \to T$, such that the followings hold.
    \begin{enumerate}
