\label{thm:ctk}
 Let $X$ be a smooth projective geometrically irreducible variety defined over a field $k$.
 \begin{enumerate}
     \item Assume that $k$ has finite $\ell$-cohomological dimension. Let $M$ be the cokernel of the cycle class map $\text{CH}^2(X) \otimes \mathbb{Z}_\ell \to H^4(X, \mathbb{Z}_\ell(2))$. Then the torsion part of $M$ is isomorphic to the quotient of $H^3_{\text{nr}}(X, \mathbb{Q}_\ell/\mathbb{Z}_\ell(2))$ by its maximal divisible subgroup.
     \item Assume that $k$ is finite or separably closed. If the Chow group of zero-cycles with rational coefficients is universally supported in a surface, then the group $H^3_{\text{nr}}(X, \mathbb{Q}_\ell/\mathbb{Z}_\ell(2))$ is finite.
 \end{enumerate}

\label{lem:H2d}
    Let $\mathcal{X}^0 \to B^0$ be a smooth projective family of relative dimension $d$ of separably rationally connected varieties over a smooth \emph{affine} curve $B^0$ defined over an algebraically closed field.
    Then the \'etale cohomology group $H^{2d}(\mathcal{X}^0, \mathbb{Z}_\ell(d))$ is generated by the class of a section.

\label{lem:multisection}
    Let $\mathcal{X} \subset \mathbb{P}_B(E)$ be a family of complete intersections of degree $d_1, \ldots, d_c$ in $\mathbb{P}^n$ over a smooth projective curve $B$ over an algebraically closed field.
    Assume that $\sum d_i^2\leq n$.
    \begin{enumerate}
        \item The cycle class of any two sections $\sigma_1, \sigma_2 \subset \mathcal{X}$ of $\mathcal{X} \to B$ are rationally equivalent modulo lines in general fibers.
        \item More generally, if $C\subset \mathcal{X}$ is any irreducible curve such that $C \to \mathcal{X} \to B$ has degree $d\geq 1$, then the cycle class of $C$ is rationally equivalent to $d[\sigma_0]$ for a section $\sigma_0$ modulo lines in general fibers.
        \item Any curve in a fiber is rationally equivalent to a sum of lines in general fibers.
        \item The group of one-cycles modulo algebraic equivalence, $A_1(\mathcal{X})$, is a free abelian group of rank $2$, generated by the class of a section and a line in a general fiber.
    \end{enumerate}

